package co.za.millenniumsolutions.repository;
import co.za.millenniumsolutions.model.PrivateObjectReference; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository;
@Repository public class PrivateObjectReferenceRepository extends RepositorySupport { public PrivateObjectReferenceRepository(JdbcTemplate j){super(j);} public PrivateObjectReference save(PrivateObjectReference x){update("INSERT INTO private_object_reference(id,object_key,media_type,size_bytes,checksum,purpose,created_by,created_at) VALUES (?,?,?,?,?,?,?,COALESCE(?,CURRENT_TIMESTAMP)) ON CONFLICT(id) DO UPDATE SET checksum=excluded.checksum",x.id(),x.objectKey(),x.mediaType(),x.sizeBytes(),x.checksum(),x.purpose(),x.createdBy(),x.createdAt()==null?null:x.createdAt().toString()); return x;} }
